using System;
using System.IO;
using System.Text;
using Newtonsoft.Json.Linq;
using XanaduYonder.Core;
using XanaduYonder.Core.Minesweeper;
using XanaduYonder.Runtime.Minesweeper;
internal static class Program
{
    private static int passed;
    private static void Main()
    {
        Check("empty profile roundtrip creates no session",()=>{var d=new MinesweeperSaveData();var json=MinesweeperSaveCodec.Encode(d);var copy=Decode(json);for(int i=0;i<3;i++){Assert(copy.Slots[i]==null);Eq(copy.Records[i].Wins,0);}Assert(!copy.TutorialSeen);});
        Check("all three states slots mode view and raw milliseconds roundtrip",()=>{var d=Fixture();d.SelectedDifficulty=2;d.TutorialSeen=true;var copy=Decode(MinesweeperSaveCodec.Encode(d));Assert(copy.SelectedDifficulty==2&&copy.TutorialSeen);for(int i=0;i<3;i++){Assert(copy.Slots[i].SessionId==d.Slots[i].SessionId);Assert(copy.Slots[i].Board.Difficulty==i);Assert(copy.Slots[i].Board.State==d.Slots[i].Board.State);Assert(copy.Slots[i].ZoomScale==d.Slots[i].ZoomScale);}Assert(copy.Slots[1].ResultRecorded);Eq(copy.Records[1].Wins,1);});
        Check("strict fields reject every missing and unknown root slot record field",()=>{var original=JObject.Parse(MinesweeperSaveCodec.Encode(Fixture()));var paths=new[]{"", "slots[0]", "records[0]"};foreach(var path in paths){var part=path==""?original:(JObject)original.SelectToken(path);foreach(var property in part.Properties()){var copy=(JObject)original.DeepClone();var target=path==""?copy:(JObject)copy.SelectToken(path);target.Remove(property.Name);Reject(copy.ToString());}var extra=(JObject)original.DeepClone();(path==""?extra:(JObject)extra.SelectToken(path))["extra"]=true;Reject(extra.ToString());}});
        Check("duplicate keys trailing text and nonstandard JSON are rejected",()=>{string json=MinesweeperSaveCodec.Encode(Fixture());Reject(json.Replace("\"schemaVersion\":1","\"schemaVersion\":1,\"schemaVersion\":1"));Reject(json+" {}");Reject(json.Replace("\"schemaVersion\"","'schemaVersion'"));Reject(json.Replace("\"schemaVersion\":1","\"schemaVersion\":1/* comment */"));Reject(json.Substring(0,json.Length-1)+",}");});
        Check("identity versions dimensions and selected difficulty cannot coerce",()=>{foreach(var path in new[]{"schemaVersion","slots[0].rulesVersion","slots[0].width","slots[0].height","slots[0].mineCount"}){Mutate(path,new JValue("1"));Mutate(path,new JValue(1.0));Mutate(path,JValue.CreateNull());}Mutate("schemaVersion",new JValue(2));Mutate("gameId",new JValue("sudoku"));Mutate("selectedDifficulty",new JValue("easy"));Mutate("slots[0].difficulty",new JValue("expert"));Mutate("slots[0].sessionId",new JValue(Guid.Empty.ToString("D")));Mutate("slots[0].sessionId",new JValue(Guid.NewGuid().ToString("N")));Mutate("slots[0].sessionId",new JValue("AAAAAAAA-AAAA-AAAA-AAAA-AAAAAAAAAAAA"));});
        Check("numeric records and time require bounded unsigned decimal strings",()=>{foreach(var path in new[]{"slots[0].elapsedMilliseconds","records[0].wins","records[0].losses"})foreach(var value in new JToken[]{new JValue(1),new JValue(-1),new JValue("-1"),new JValue("+1"),new JValue("1.2"),new JValue("1e3"),new JValue(""),new JValue(" 1"),new JValue("9223372036854775808"),JValue.CreateNull()})Mutate(path,value);var d=Fixture();d.Slots[0].ElapsedMilliseconds=long.MaxValue;d.Records[0].Losses=long.MaxValue;var copy=Decode(MinesweeperSaveCodec.Encode(d));Eq(copy.Slots[0].ElapsedMilliseconds,long.MaxValue);});
        Check("oversized integer and exponent tokens fail without throwing",()=>{string json=MinesweeperSaveCodec.Encode(Fixture());Reject(json.Replace("\"schemaVersion\":1","\"schemaVersion\":999999999999999999999999999999999999999999999"));Reject(json.Replace("\"zoomScale\":0.617123","\"zoomScale\":1e400"));Reject(json.Replace("\"zoomScale\":0.617123","\"zoomScale\":999999999999999999999999999999999999999999999999999999999999999999999999999999999999999"));});
        Check("booleans enum null arrays and wrong lengths are rejected",()=>{foreach(var path in new[]{"tutorialSeen","slots[0].generated","slots[0].fullscreen","slots[0].resultRecorded","slots[0].mines[0]","slots[0].flags[0]","slots[0].revealed[0]"}){Mutate(path,new JValue(1));Mutate(path,new JValue("false"));Mutate(path,JValue.CreateNull());}foreach(var path in new[]{"slots","records","slots[0].mines","slots[0].revealed","slots[0].flags"}){Mutate(path,JValue.CreateNull());Mutate(path,new JArray());}Mutate("records[0]",JValue.CreateNull());Mutate("slots[0].state",new JValue("Paused"));Mutate("slots[0].inputMode",new JValue("Reveal"));});
        Check("normal viewport rejects string nonfinite and out of range numbers",()=>{foreach(var path in new[]{"slots[0].zoomScale","slots[0].centerColumn","slots[0].centerRow"}){Mutate(path,new JValue("1"));Mutate(path,new JValue(-.01));Mutate(path,new JValue(100));Mutate(path,JValue.CreateNull());}Mutate("slots[0].zoomScale",new JValue(.49));Mutate("slots[0].zoomScale",new JValue(2.01));Reject(MinesweeperSaveCodec.Encode(Fixture()).Replace("\"zoomScale\":0.617123","\"zoomScale\":NaN"));});
        Check("board invariants are checked before any profile escapes",()=>{Mutate("slots[0].generated",new JValue(false));Mutate("slots[0].firstRevealIndex",JValue.CreateNull());Mutate("slots[0].firstRevealIndex",new JValue(500));Mutate("slots[0].state",new JValue("Won"));Mutate("slots[0].detonatedIndex",new JValue(0));Mutate("slots[0].resultRecorded",new JValue(true));Mutate("slots[0].flags[40]",new JValue(true));Mutate("slots[0].mines[40]",new JValue(true));Mutate("slots[1].resultRecorded",new JValue(false));Mutate("records[1].wins",new JValue("0"));Mutate("records[1].bestMilliseconds",new JValue("999999"));Mutate("records[0].bestMilliseconds",new JValue("1"));});
        Check("ready zero time and ungenerated arrays are validated",()=>{var p=new MinesweeperProfile();var s=new MinesweeperSession(0,new RandomSource());p.Capture(s);var root=JObject.Parse(MinesweeperSaveCodec.Encode(p.Export()));root["slots"][0]["elapsedMilliseconds"]="1";Reject(root.ToString());root["slots"][0]["elapsedMilliseconds"]="0";root["slots"][0]["revealed"][0]=true;Reject(root.ToString());});
        Check("duplicate session IDs across independent slots reject full profile",()=>{var root=JObject.Parse(MinesweeperSaveCodec.Encode(Fixture()));root["slots"][2]["sessionId"]=root["slots"][0]["sessionId"].DeepClone();Reject(root.ToString());});
        Check("size and depth bounds reject without partial decode",()=>{Reject(new string(' ',MinesweeperSaveCodec.MaximumLength+1));Reject("["+new string('[',20)+"0"+new string(']',20)+"]");Reject("{\"x\":\""+new string('汉',100000)+"\"}");});
        Check("file save creates primary and preserves previous valid atomic backup",()=>WithDirectory(dir=>{var store=new MinesweeperSaveStore(dir);Assert(store.Load(out var warning)==null&&warning==null);var a=Fixture();Assert(store.TrySave(a,out var error),error);a.SelectedDifficulty=2;Assert(store.TrySave(a,out error),error);Assert(!File.Exists(store.SavePath+".tmp"));Eq(store.Load(out warning).SelectedDifficulty,2);Eq(Decode(File.ReadAllText(store.SavePath+".bak")).SelectedDifficulty,0);}));
        Check("corrupt main recovers entire backup and never overwrites valid backup",()=>WithDirectory(dir=>{var store=new MinesweeperSaveStore(dir);var data=Fixture();Assert(store.TrySave(data,out var error),error);data.SelectedDifficulty=2;Assert(store.TrySave(data,out error),error);string backup=File.ReadAllText(store.SavePath+".bak");File.WriteAllText(store.SavePath,"{broken");var recovered=store.Load(out var warning);Assert(recovered!=null&&warning!=null);Eq(recovered.SelectedDifficulty,0);Assert(store.TrySave(recovered,out error),error);Assert(File.ReadAllText(store.SavePath+".bak")==backup);Assert(store.Load(out warning)!=null&&warning==null);}));
        Check("invalid save preserves committed files and storage failure reports false",()=>WithDirectory(dir=>{var store=new MinesweeperSaveStore(dir);var data=Fixture();Assert(store.TrySave(data,out var error),error);string before=File.ReadAllText(store.SavePath);data.Slots[0].ZoomScale=.1;Assert(!store.TrySave(data,out error)&&error!=null);Assert(File.ReadAllText(store.SavePath)==before);string blocked=Path.Combine(dir,"file");File.WriteAllText(blocked,"content");Assert(!new MinesweeperSaveStore(blocked).TrySave(Fixture(),out error)&&error!=null);}));
        Check("invalid UTF8 oversized and double corrupt files yield explicit warning",()=>WithDirectory(dir=>{var store=new MinesweeperSaveStore(dir);File.WriteAllBytes(store.SavePath,new byte[]{0xff,0xfe});Assert(store.Load(out var warning)==null&&warning!=null);File.WriteAllBytes(store.SavePath,new byte[MinesweeperSaveCodec.MaximumLength+1]);Assert(store.Load(out warning)==null&&warning!=null);File.WriteAllText(store.SavePath+".bak","null");Assert(store.Load(out warning)==null&&warning!=null);}));
        Check("backup terminal restoration and repeat saves cannot double records",()=>WithDirectory(dir=>{var store=new MinesweeperSaveStore(dir);var data=Fixture();Assert(store.TrySave(data,out var error),error);Assert(store.TrySave(data,out error),error);File.WriteAllText(store.SavePath,"bad");var p=new MinesweeperProfile(store.Load(out var warning));var s=new MinesweeperSession(p.GetSlot(1),new RandomSource());p.Capture(s);Assert(store.TrySave(p.Export(),out error),error);Eq(p.GetRecord(1).Wins,1);Eq(store.Load(out warning).Records[1].Wins,1);}));
        Check("unreadable existing save reports failure and permissions recovery retries normally",()=>WithDirectory(dir=>{
            if (OperatingSystem.IsWindows()) return;
            var store=new MinesweeperSaveStore(dir);var data=Fixture();Assert(store.TrySave(data,out var error),error);
            var original=File.GetUnixFileMode(dir);
            try { File.SetUnixFileMode(dir,UnixFileMode.None); Assert(store.Load(out var warning)==null&&warning!=null,"Unreadable existing save was treated as a missing file."); }
            finally { File.SetUnixFileMode(dir,original); }
            var recovered=store.Load(out var restoredWarning);Assert(recovered!=null&&restoredWarning==null);Eq(recovered.Records[1].Wins,1);
            data.SelectedDifficulty=2;Assert(store.TrySave(data,out error),error);Eq(store.Load(out restoredWarning).SelectedDifficulty,2);
        }));
        Check("write failure then successful retry keeps one terminal result",()=>WithDirectory(dir=>{
            string blocked=Path.Combine(dir,"blocked");File.WriteAllText(blocked,"temporary obstacle");var store=new MinesweeperSaveStore(blocked);
            var profile=new MinesweeperProfile(Fixture());var session=new MinesweeperSession(profile.GetSlot(1),new RandomSource());var save=profile.Capture(session);
            Assert(!store.TrySave(save,out var error)&&error!=null);Eq(profile.GetRecord(1).Wins,1);
            File.Delete(blocked);Assert(store.TrySave(profile.Capture(session),out error),error);
            var recovered=store.Load(out var warning);Assert(recovered!=null&&warning==null&&recovered.Slots[1].ResultRecorded);Eq(recovered.Records[1].Wins,1);
        }));
        Console.WriteLine("Minesweeper persistence: "+passed+" passed");
    }
    private static MinesweeperSaveData Fixture(){var p=new MinesweeperProfile();for(int d=0;d<3;d++){long time=0;var s=new MinesweeperSession(d,new RandomSource(),()=>time);s.Execute(s.SessionId,d==0?40:100);time=1234;if(d==1){var b=s.Game.GetSnapshot();for(int i=0;i<b.Width*b.Height;i++)if(!b.IsMine(i))s.Execute(s.SessionId,i);}else if(d==2){var b=s.Game.GetSnapshot();for(int i=0;i<b.Width*b.Height;i++)if(b.IsMine(i)){s.Execute(s.SessionId,i);break;}}s.SetView(true,.617123,2.34,6.78);p.Capture(s);}return p.Export();}
    private static void Mutate(string path,JToken token){var root=JObject.Parse(MinesweeperSaveCodec.Encode(Fixture()));root.SelectToken(path).Replace(token.DeepClone());Reject(root.ToString());}
    private static MinesweeperSaveData Decode(string json){Assert(MinesweeperSaveCodec.TryDecode(json,out var d,out var reason),reason);return d;}
    private static void Reject(string json){Assert(!MinesweeperSaveCodec.TryDecode(json,out var d,out var reason),"Accepted invalid JSON: "+json.Substring(0,Math.Min(json.Length,100)));Assert(d==null&&reason!=null);}
    private static void WithDirectory(Action<string> test){string dir=Path.Combine(AppContext.BaseDirectory,"xanadu-minesweeper-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{test(dir);}finally{Directory.Delete(dir,true);}}
    private static void Eq(long actual,long expected){Assert(actual==expected,actual+" != "+expected);}
    private static void Assert(bool value,string reason="Assertion failed"){if(!value)throw new Exception(reason);}
    private static void Check(string name,Action test){test();passed++;Console.WriteLine("PASS "+name);}
    private sealed class RandomSource:IRandomSource{private readonly Random random=new Random(8);public int Next(int n){return random.Next(n);}}
}
